  t.schemaVersion=3;t.id=String(t.id??t.Id??('diagram-'+Date.now().toString(36)));t.name=String(t.name??t.Name??'Mẫu sơ đồ');t.kind=String(t.kind??t.Kind??'topology').toLowerCase();t.sourceMethod=String(t.sourceMethod??t.SourceMethod??'');t.sourceFile=String(t.sourceFile??t.SourceFile??'');t.autoLearn=t.autoLearn??t.AutoLearn;
